import json
d = json.load(open('/tmp/jira_describe.json'))
# Find metadataFile in any key
def find_key(obj, key):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k.lower() in (key.lower(), key):
                print(f'Found: {k} = {v}')
            find_key(v, key)
    elif isinstance(obj, list):
        for item in obj:
            find_key(item, key)
find_key(d, 'metadata')
find_key(d, 'file')
print(json.dumps(d, indent=2)[:2000])
"

python3 -c "
import json
d = json.load(open('/tmp/jira_describe.json'))
rf = d['Data']['RequestFields']
# Print required fields and reporter field
print('=== ALL FIELDS (required first) ===')
for f in rf:
    if f.get('Required'):
        print(f'REQUIRED: {f[\"Name\"]} ({f[\"DisplayName\"]})')
# Find reporter
for f in rf:
    if 'reporter' in f['Name'].lower() or 'reporter' in f.get('DisplayName','').lower():
        print(f'REPORTER FIELD: {json.dumps(f, indent=2)}')
# Find summary
